// P22 in the pure port (no hybrid): the boss-B fights, Ganon, Zelda and the ending run through
// src/headless.js against the oracle (RAM + SRAM, every frame), whole movie, diff 0 required.
// SRAM p22-items.sav (first quest, every item). Generated by tests/game/p22-make-movies.mjs.
//  * boss-moldorm       level 2 room $3E: the two moldorm chains.
//  * boss-gleeok        level 4: gleeok with 2 heads (flying head after a neck dies).
//  * boss-gleeok3       level 6: gleeok with 3 heads.
//  * boss-gleeok4       level 8: gleeok with 4 heads.
//  * boss-patra         level 9: both Patras (big / small orbit of the children).
//  * boss-ganon         level 9: Ganon's scene, sword (invisible), silver arrow (brown), death, triforce.
//  * rescue-zelda       level 9: the guard fires, Zelda (mode $13).
//  * ending-from-ganon  the ending, the credits and the start of the second quest.
// Skipped without roms/zelda.nes or jsnes, or while a movie has not been generated.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { join, basename } from 'node:path';
import { readFileSync, existsSync } from 'node:fs';
import { hasJsnes } from '../../tools/oracle/lib/jsnes-loader.mjs';
import { romExists, loadRomFile } from '../../tools/oracle/lib/rom-file.mjs';
import { loadMovie } from '../../tools/oracle/lib/movie.mjs';
import { TraceCollector } from '../../tools/oracle/lib/trace.mjs';
import { compareTraces, loadIgnoreConfig } from '../../tools/oracle/lib/diff-core.mjs';
import { runPort } from '../../tools/oracle/lib/port-adapter.mjs';
import { ROOT } from '../core/helpers.mjs';

const skip = !romExists() ? 'roms/zelda.nes not present' : !(await hasJsnes()) ? 'jsnes not installed' : false;
const MOVIES = join(ROOT, 'tests/oracle/movies');
// Boss types each movie must show.
const REQUIRED = {
  'boss-moldorm': [0x41],
  'boss-gleeok': [0x43, 0x46],
  'boss-gleeok3': [0x44, 0x46],
  'boss-gleeok4': [0x45, 0x46],
  'boss-patra': [0x47, 0x48, 0x25, 0x26],
  'boss-ganon': [0x3e],
  'rescue-zelda': [0x3e, 0x37, 0x3f],
  'ending-from-ganon': [0x3e, 0x37, 0x3f],
};

for (const name of Object.keys(REQUIRED)) {
  const missing = !existsSync(join(MOVIES, `${name}.zmv`)) && `${name}.zmv not generated`;
  test(`P22 pure port ${name}: diff 0 on every frame`, { skip: skip || missing, timeout: 1800000 }, async (t) => {
    const rom = loadRomFile();
    const expect = JSON.parse(readFileSync(join(MOVIES, `${name}.expect.json`), 'utf8'));
    const sram = new Uint8Array(readFileSync(join(MOVIES, basename(expect.sram))));
    const movie = loadMovie(join(MOVIES, `${name}.zmv`));
    const { Oracle } = await import('../../tools/oracle/lib/nes-oracle.mjs');
    const V = await import('../../src/core/vars.js');
    const a = new TraceCollector({});
    const types = new Set();
    const modes = new Set();
    (await Oracle.create({ rom: rom.bytes, sram, powerOnFill: 0 })).run(movie, {
      write(rec) {
        a.write(rec);
        modes.add(rec.ram[V.GameMode]);
        for (let i = 1; i < 0x0c; i++) types.add(rec.ram[V.ObjType + i]);
      },
      close() {},
    });
    for (const ty of [...REQUIRED[name], ...(expect.bossTypes ?? [])]) assert.ok(types.has(ty), `${name}: no monster of type $${ty.toString(16)}`);
    for (const m of expect.reaches.GameMode ?? []) assert.ok(modes.has(m), `${name}: never in mode $${m.toString(16)}`);
    const b = new TraceCollector({});
    await runPort({ rom: rom.bytes, sram, inputs: movie, sink: b });
    t.diagnostic(`${b.frames.length} frames; events: ${(expect.events ?? []).join('; ') || 'none'}`);
    const report = compareTraces(a, b, { ignore: loadIgnoreConfig().ignore, compareFb: false, maxReportFrames: Infinity });
    // Nested NMIs of the original (an NMI longer than a video frame re-enables the NMI inside the next
    // vblank: the second NMI runs before the first one's RTI). The oracle's frame k (first RTI) then
    // holds two NMIs of work (FrameCounter +2) and frame k+1 none (+0); the port, one NMI per frame
    // without a CPU cycle model (docs/TIMING.md), is one NMI behind at k only and equal again at k+1.
    // Those frames k are the only divergences tolerated; everything else must be identical.
    const nested = new Set();
    for (let i = 1; i + 1 < a.frames.length; i++) {
      const fc = (j) => a.frames[j].ram[V.FrameCounter];
      if (((fc(i) - fc(i - 1)) & 0xff) === 2 && fc(i + 1) === fc(i)) nested.add(a.frames[i].frame);
    }
    if (nested.size) t.diagnostic(`nested NMIs in the original at frames ${[...nested].join(', ')}`);
    const bad = report.frames.filter((f) => !nested.has(f.frame));
    assert.equal(report.missing.length, 0, `${name}: frames missing in the port`);
    assert.equal(bad.length, 0, `${name}: first divergence at frame ${bad[0]?.frame}: `
      + JSON.stringify(bad[0] && { ram: bad[0].ram.slice(0, 8), sram: bad[0].sram.slice(0, 8) }));
  });
}
